INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'fukuoka-ymca', '福冈YMCA日本语学校', '福岡YMCA日本語学校', '天神校：福冈市中央区天神3-4-7 天神旭大楼2F；七隈校：福冈市城南区七隈1-1-10', '官网已公告受理2027年4月入学的留学签进学日语课程；本批未取得校方公开的2027长课费用表，已移除旧的“约80万日元/年”报价。', '本批未核实2027长课的付款与分期规则。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '生活/就业日语课程为3个月至2年；进学日语课程为1年6月或2年', '官网确认两类长课均可申请留学签；具体资格、材料与日语条件以2027申请要项为准。', '本批未核实。', '官网公告2027年4月留学签进学日语课程正在受理；其他入学期依校方当期要项确认。', '官网区分生活/就业与进学日语；2027年4月进学课程已开始受理，但不以未公开费用替代真实报价。', 'https://fukuoka-ymca.sakura.ne.jp/japanese/', '["天神与七隈两校","生活/就业日语","进学日语","2027年4月留学签受理中"]'::jsonb, '[{"name":"生活/就业日语课程","description":"3个月至2年，可申请留学签。"},{"name":"进学日语课程","description":"1年6月或2年，面向日本大学等高等教育机构升学，可申请留学签。"}]'::jsonb, '{"enrollmentFee":"2027费用待校方公布","annualTuition":"2027费用待校方公布","materialsFee":"2027费用待校方公布","totalFirstYear":"2027费用待校方公布"}'::jsonb, '["计划福冈生活、就职或升学","申请2027年4月进学课程","可等待校方发布2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'kumamoto-ymca', '熊本YMCA日本语学校', '熊本YMCA日本語学校', '熊本县熊本市中央区段山本町4-1', '官网当前2年课程总额1,500,000日元、1年6月课程总额1,150,000日元（分别含选考20,000、入学80,000、授课1,280,000/960,000、教材80,000/60,000、活动40,000/30,000）；留学签学生另须加入学生24小时共济，约13,000日元/年。官网未标注为2027费用。', '本批未核实分期支付规则。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '2年或1年6月', '完成12年以上学校教育；原则上须具相当于JLPT N5（CEFR A1）以上的考试证明，并通过面试等审查；须能保障在学费用。', '本批未核实。', '留学签：4月（2年）或10月（1年6月）；各期额满可能提前截止。', '官网公开全程费用与留学签申请资格；费用页未标为2027，未把现行表包装为2027承诺。', 'https://www.kumamoto-ymca.or.jp/nihongo-e/32672.html', '["全日制日语科","4月2年与10月1年6月","N5/A1相当申请资格","与专门学校学生交流"]'::jsonb, '[{"name":"全日制日语科","description":"留学签2年或1年6月课程，按日语能力分级，并通过面试等确认学习意愿与日语能力。"}]'::jsonb, '{"enrollmentFee":"入学金80,000日元（另有选考料20,000日元）","annualTuition":"2年课程授课费1,280,000日元；1年6月课程960,000日元（均为全程金额）","materialsFee":"2年80,000日元；1年6月60,000日元","totalFirstYear":"官网按全程列示：2年1,500,000日元、1年6月1,150,000日元","otherFees":"留学签学生另须加入学生24小时共济，约13,000日元/年；当前页面未标为2027价格"}'::jsonb, '["计划熊本全日制留学签课程","已具N5/A1相当证明","能以申请时要项确认2027费用"]'::jsonb
);
INSERT INTO "LanguageSchool" (slug, name, "nameJa", location, tuition, "paymentTerm", "attendanceRequirement", duration, "visaRequirement", "minimumStudyForVocational", intake, highlights, website, "featuresJson", "programsJson", "tuitionBreakdownJson", "suitableForJson") VALUES (
  'hiroshima-ymca', '广岛YMCA日本语学校', '広島YMCA日本語学校', '广岛县广岛市中区八丁堀7-11 广岛YMCA1号馆', '官网公开的2026年留学签要项：4月1年/2年首年817,500日元，10月1年6月首年469,000日元；其后2027年度第二年费用697,500日元。该表适用于2026年入学者，2027年新入学费用尚待校方发布。', '2026要项规定初年度一次缴清，次年度可分期；2027新入学付款规则待校方公布。', '本批未核实官方对在留资格维持的具体出勤率门槛。', '4月入学为1年或2年；10月入学为1年6月', '2026要项要求完成12年教育、150小时日语学习经历且具JLPT N5/J-TEST F级等；另须明确学习目的、经费保障和广岛市近郊身元保证人或合作机构担保。2027条件待校方最新要项。', '本批未核实。', '4月（1年或2年）/10月（1年6月）；2027新入学日程待校方公布。', '官网公开广岛中心校址和全日制、短期等课程；已将2026费用与2027新生报价严格区分。', 'https://www.hymca.jp/jp/', '["广岛YMCA专门学校日语课程","4月/10月留学签课程","全日制及短期课程","与专门学校学生交流"]'::jsonb, '[{"name":"言语沟通科日语课程（留学签）","description":"4月开1年/2年、10月开1年6月；大学和专门学校升学、商务及生活日语均为官网列示目标。"},{"name":"其他日语课程","description":"官网另列每周2/3日、短期、私人和初学者志愿课程；具体费用与日程按校方确认。"}]'::jsonb, '{"enrollmentFee":"入学金100,000日元（另有出愿料20,000日元）","annualTuition":"2026年入学者首年授课费650,000日元；2027年度第二年650,000日元","materialsFee":"首年教材料40,000日元；2027年度第二年40,000日元","totalFirstYear":"2026年4月入学者817,500日元；该金额不代表2027年新入学报价","otherFees":"保险首年7,500日元；2年全程1,515,000日元，1年6月全程1,166,500日元（均基于2026要项）"}'::jsonb, '["计划广岛全日制或短期日语课程","符合留学签材料条件","能以2027最新要项确认费用"]'::jsonb
);
COMMIT;
